  final Parity parity;
  final int stopBits;
  final bool autoReconnect;
  final FlowControl flowControl;

  const SerialConfig({
    required this.portName,
    required this.baudRate,
    required this.dataBits,
    required this.parity,
    required this.stopBits,
    required this.autoReconnect,
    required this.flowControl,
  });

  @override
  int get hashCode =>
      portName.hashCode ^
      baudRate.hashCode ^
      dataBits.hashCode ^
      parity.hashCode ^
      stopBits.hashCode ^
      autoReconnect.hashCode ^
      flowControl.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SerialConfig &&
          runtimeType == other.runtimeType &&
          portName == other.portName &&
          baudRate == other.baudRate &&
          dataBits == other.dataBits &&
          parity == other.parity &&
          stopBits == other.stopBits &&
          autoReconnect == other.autoReconnect &&
          flowControl == other.flowControl;
}

class SnapshotReply {
  final AppSnapshot? snapshot;
  final CoreError? error;

  const SnapshotReply({this.snapshot, this.error});

  @override
  int get hashCode => snapshot.hashCode ^ error.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SnapshotReply &&
          runtimeType == other.runtimeType &&
          snapshot == other.snapshot &&
          error == other.error;
}

class SubscribeReply {
  final AppSnapshot? snapshot;
  final SubscriptionHandle? subscription;
  final CoreError? error;

  const SubscribeReply({this.snapshot, this.subscription, this.error});

  @override
  int get hashCode =>
      snapshot.hashCode ^ subscription.hashCode ^ error.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SubscribeReply &&
          runtimeType == other.runtimeType &&
          snapshot == other.snapshot &&
          subscription == other.subscription &&
          error == other.error;
}
